#if DEBUG
import SwiftUI
import PencilKit

/// Demo content injected when launched with `-DemoMode`. Used for App Store captures only —
/// never compiled in release builds.
///
/// Handwriting comes from `DemoInk` (generated by `scripts/generate_demo_ink.py`) in the
/// device's language, so every store locale shows readable, real-looking notes.
enum DemoData {
    static var isEnabled: Bool { arguments.contains("-DemoMode") }
    static var isPro: Bool { isEnabled && arguments.contains("-DemoPro") }

    static var initialScreen: String? { value(after: "-OpenScreen") }

    private static var arguments: [String] { ProcessInfo.processInfo.arguments }
    private static func value(after flag: String) -> String? {
        guard let i = arguments.firstIndex(of: flag), i + 1 < arguments.count else { return nil }
        return arguments[i + 1]
    }

    /// ko / en / ja / zh, from the app's resolved localization.
    static var locale: String {
        let code = Bundle.main.preferredLocalizations.first ?? "ko"
        if code.hasPrefix("zh") { return "zh" }
        return ["ko", "en", "ja"].first { code.hasPrefix($0) } ?? "en"
    }

    // MARK: - Pages

    static func buildPages() -> [NotePage] {
        let titles = pageTitles[locale] ?? pageTitles["en"]!
        var pages = [
            NotePage(title: titles[0], drawing: tripDrawing(), paperStyle: .blank, createdAt: daysAgo(0)),
            NotePage(title: titles[1], drawing: diaryDrawing(), paperStyle: .lines, createdAt: daysAgo(1)),
            NotePage(title: titles[2], drawing: studyDrawing(), paperStyle: .study, createdAt: daysAgo(2)),
            NotePage(title: titles[3], drawing: weeklyDrawing(), paperStyle: .weekly, createdAt: daysAgo(3)),
            NotePage(title: titles[4], drawing: meetingDrawing(), paperStyle: .cornell, createdAt: daysAgo(5)),
        ]
        // iPad shows the page at writing size on a much wider canvas; enlarge the demo ink so
        // captures read like the iPhone ones.
        if inkScale != 1 {
            let t = CGAffineTransform(scaleX: inkScale, y: inkScale)
            pages = pages.map { NotePage(id: $0.id, title: $0.title, drawing: $0.drawing.transformed(using: t),
                                          paperStyle: $0.paperStyle, createdAt: $0.createdAt) }
        }
        if let count = value(after: "-DemoPageCount").flatMap(Int.init), (1...5).contains(count) {
            pages = Array(pages.prefix(count))
        }
        return pages
    }

    private static let pageTitles: [String: [String]] = [
        "ko": ["제주 여행 계획", "오늘의 일기", "수학 오답노트", "이번 주 할 일", "기획 회의록"],
        "en": ["Weekend trip", "Journal", "Math review", "This week", "Planning meeting"],
        "ja": ["週末の旅行", "今日の日記", "数学の復習ノート", "今週のやること", "企画会議メモ"],
        "zh": ["周末旅行", "今天的日记", "数学错题本", "本周待办", "策划会议记录"],
    ]

    /// The part of the trip page holding the mountain sketch and its note — what the
    /// selection and transparent-export captures frame.
    static var sketchSelection: NoteSelection {
        NoteSelection(rect: CGRect(x: 24, y: 300, width: 400, height: 190)
            .applying(CGAffineTransform(scaleX: inkScale, y: inkScale)))!
    }

    private static var inkScale: CGFloat { UIDevice.current.userInterfaceIdiom == .pad ? 1.7 : 1 }

    private static func daysAgo(_ days: Double) -> Date { Date().addingTimeInterval(-86400 * days) }

    // RGB, not UIColor(white:) — PencilKit renders grayscale-space ink nearly transparent.
    private static let black = UIColor(red: 0.1, green: 0.1, blue: 0.12, alpha: 1)
    private static let blue = UIColor(red: 0.16, green: 0.38, blue: 0.93, alpha: 1)
    private static let red = UIColor(red: 0.89, green: 0.22, blue: 0.24, alpha: 1)
    private static let green = UIColor(red: 0.13, green: 0.6, blue: 0.36, alpha: 1)

    private static func tripDrawing() -> PKDrawing {
        var s: [PKStroke] = []
        s += text("trip_title", at: CGPoint(x: 30, y: 92), size: 46, maxWidth: 330)
        s += [wavyUnderline(from: CGPoint(x: 30, y: 108), width: 300, color: blue)]
        s += star(center: CGPoint(x: 392, y: 70), radius: 20, color: red)
        for (i, id) in ["trip_1", "trip_2", "trip_3"].enumerated() {
            let y = 168 + CGFloat(i) * 48
            s += box(CGRect(x: 30, y: y - 22, width: 22, height: 22), color: black)
            if i < 2 { s += [check(in: CGRect(x: 30, y: y - 30, width: 28, height: 28), color: blue)] }
            s += text(id, at: CGPoint(x: 66, y: y), size: 29, maxWidth: 350)
        }
        s += mountains(origin: CGPoint(x: 40, y: 330), width: 210, height: 140)
        s += [arrow(from: CGPoint(x: 262, y: 420), to: CGPoint(x: 312, y: 384), color: red)]
        s += text("must_go", at: CGPoint(x: 300, y: 370), size: 32, maxWidth: 120, color: red)
        s += box(CGRect(x: 26, y: 528, width: 96, height: 46), color: green, rough: true)
        s += text("pack", at: CGPoint(x: 36, y: 562), size: 30, maxWidth: 80, color: green)
        s += text("pack_items", at: CGPoint(x: 32, y: 622), size: 27, maxWidth: 380)
        return PKDrawing(strokes: s)
    }

    private static func diaryDrawing() -> PKDrawing {
        // Lines paper: rules every 35pt from y = 100.
        let ids = ["diary_1", "diary_2", "diary_3", "diary_4", "diary_5"]
        let s = ids.enumerated().flatMap { i, id in
            text(id, at: CGPoint(x: 28, y: 131 + CGFloat(i) * 70), size: 27, maxWidth: 390)
        }
        return PKDrawing(strokes: s + smile(center: CGPoint(x: 380, y: 470), radius: 18, color: blue))
    }

    private static func studyDrawing() -> PKDrawing {
        var s: [PKStroke] = []
        s += text("math_q", at: CGPoint(x: 30, y: 116), size: 28, maxWidth: 200, color: blue)
        s += text("math_q1", at: CGPoint(x: 30, y: 196), size: 34, maxWidth: 360)
        s += text("math_a", at: CGPoint(x: 30, y: 276), size: 28, maxWidth: 200, color: red)
        s += text("math_a1", at: CGPoint(x: 30, y: 356), size: 32, maxWidth: 360, color: red)
        s += text("math_a2", at: CGPoint(x: 30, y: 436), size: 32, maxWidth: 360, color: red)
        s += [circle(center: CGPoint(x: 120, y: 424), radiusX: 104, radiusY: 30, color: red)]
        s += text("math_tip", at: CGPoint(x: 210, y: 516), size: 26, maxWidth: 200, color: blue)
        return PKDrawing(strokes: s)
    }

    private static func weeklyDrawing() -> PKDrawing {
        var s: [PKStroke] = []
        for (i, id) in ["week_1", "week_2", "week_3", "week_4"].enumerated() {
            let y = 90 + CGFloat(i) * 64
            s += text(id, at: CGPoint(x: 64, y: y), size: 28, maxWidth: 340, color: i == 3 ? red : black)
            s += box(CGRect(x: 28, y: y - 24, width: 22, height: 22), color: black)
            if i < 2 { s += [check(in: CGRect(x: 28, y: y - 32, width: 28, height: 28), color: green)] }
        }
        return PKDrawing(strokes: s)
    }

    private static func meetingDrawing() -> PKDrawing {
        var s: [PKStroke] = []
        for (i, (cue, note)) in [("meet_cue1", "meet_1"), ("meet_cue2", "meet_2"), ("meet_cue3", "meet_3")].enumerated() {
            let y = 160 + CGFloat(i) * 140
            s += text(cue, at: CGPoint(x: 60, y: y), size: 64, maxWidth: 600, color: blue)
            s += text(note, at: CGPoint(x: 800, y: y), size: 64, maxWidth: 2000)
        }
        return PKDrawing(strokes: s)
    }

    // MARK: - Handwriting library

    static func buildSnippets() -> [InkSnippet] {
        let names: [String: [String]] = [
            "ko": ["체크", "화살표", "별표", "좋아요", "중요", "확인 필요", "완료", "웃는 얼굴"],
            "en": ["Check", "Arrow", "Star", "Nice", "Key point", "Check this", "Done", "Smile"],
            "ja": ["チェック", "矢印", "星", "いいね", "重要", "要確認", "完了", "スマイル"],
            "zh": ["对勾", "箭头", "星标", "很好", "重点", "待确认", "完成", "笑脸"],
        ]
        let n = names[locale] ?? names["en"]!
        let size = CGSize(width: 160, height: 110)
        let center = CGPoint(x: 80, y: 55)
        let drawings: [[PKStroke]] = [
            [check(in: CGRect(x: 40, y: 15, width: 80, height: 80), color: green)],
            [arrow(from: CGPoint(x: 20, y: 80), to: CGPoint(x: 140, y: 30), color: red)],
            star(center: center, radius: 42, color: red),
            text("snip_good", centeredAt: center, size: 44, maxWidth: 110, color: blue)
                + [circle(center: center, radiusX: 74, radiusY: 46, color: blue)],
            text("snip_important", centeredAt: center, size: 50, maxWidth: 110, color: red)
                + [wavyUnderline(from: CGPoint(x: 28, y: 84), width: 104, color: red)],
            text("snip_check", centeredAt: CGPoint(x: 88, y: 55), size: 38, maxWidth: 120)
                + box(CGRect(x: 8, y: 22, width: 146, height: 66), color: black, rough: true),
            text("snip_done", centeredAt: CGPoint(x: 96, y: 55), size: 46, maxWidth: 90, color: green)
                + [check(in: CGRect(x: 6, y: 30, width: 40, height: 40), color: green)],
            smile(center: center, radius: 40, color: blue),
        ]
        return drawings.enumerated().map { i, strokes in
            InkSnippet(id: UUID(), title: n[i], drawing: PKDrawing(strokes: strokes), size: size,
                       createdAt: daysAgo(Double(i)))
        }
    }

    // MARK: - Ink builders

    private static func pen(_ points: [CGPoint], color: UIColor, width: CGFloat) -> PKStroke {
        // PencilKit treats points as spline control points; densify so corners stay crisp.
        var dense: [CGPoint] = []
        for (a, b) in zip(points, points.dropFirst()) {
            let steps = max(1, Int((hypot(b.x - a.x, b.y - a.y) / 1.5).rounded(.up)))
            dense += (0..<steps).map { k in
                let t = CGFloat(k) / CGFloat(steps)
                return CGPoint(x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t)
            }
        }
        if let last = points.last { dense.append(last) }
        let strokePoints = dense.enumerated().map { i, pt in
            PKStrokePoint(location: pt, timeOffset: TimeInterval(i) * 0.008,
                          size: CGSize(width: width, height: width), opacity: 1, force: 1,
                          azimuth: 0, altitude: .pi / 2)
        }
        return PKStroke(ink: PKInk(.pen, color: color),
                        path: PKStrokePath(controlPoints: strokePoints, creationDate: Date()))
    }

    /// Handwritten text with its baseline-left at `origin`, `size` = em height in points.
    private static func text(_ id: String, at origin: CGPoint, size: CGFloat, maxWidth: CGFloat,
                             color: UIColor = black) -> [PKStroke] {
        guard let entry = DemoInk.table[locale]?[id] ?? DemoInk.table["en"]?[id],
              let data = Data(base64Encoded: entry.data) else { return [] }
        let scale = min(size, maxWidth * 1000 / max(1, CGFloat(entry.advance))) / 1000
        let width = max(2.5, CGFloat(entry.width) * scale * 1.25)
        return decode(data).map { stroke in
            pen(stroke.map { CGPoint(x: origin.x + $0.x * scale, y: origin.y + $0.y * scale) },
                color: color, width: width)
        }
    }

    private static func text(_ id: String, centeredAt c: CGPoint, size: CGFloat, maxWidth: CGFloat,
                             color: UIColor = black) -> [PKStroke] {
        let strokes = text(id, at: .zero, size: size, maxWidth: maxWidth, color: color)
        let bounds = strokes.reduce(CGRect.null) { $0.union($1.renderBounds) }
        guard !bounds.isNull else { return [] }
        let t = CGAffineTransform(translationX: c.x - bounds.midX, y: c.y - bounds.midY)
        return strokes.map { var s = $0; s.transform = s.transform.concatenating(t); return s }
    }

    private static func decode(_ data: Data) -> [[CGPoint]] {
        let values: [Int16] = data.withUnsafeBytes { raw in
            (0..<(raw.count / 2)).map { Int16(littleEndian: raw.loadUnaligned(fromByteOffset: $0 * 2, as: Int16.self)) }
        }
        var i = 1, strokes: [[CGPoint]] = []
        for _ in 0..<Int(values.first ?? 0) {
            let n = Int(values[i]); i += 1
            strokes.append((0..<n).map { k in CGPoint(x: CGFloat(values[i + k * 2]), y: CGFloat(values[i + k * 2 + 1])) })
            i += n * 2
        }
        return strokes
    }

    /// Small deterministic wobble so shapes look drawn by hand.
    private static func jitter(_ p: CGPoint, _ k: Int, _ amount: CGFloat = 1.2) -> CGPoint {
        CGPoint(x: p.x + CGFloat(sin(Double(k) * 12.9898)) * amount, y: p.y + CGFloat(cos(Double(k) * 78.233)) * amount)
    }

    private static func check(in r: CGRect, color: UIColor) -> PKStroke {
        pen([CGPoint(x: r.minX, y: r.midY), CGPoint(x: r.minX + r.width * 0.2, y: r.midY + r.height * 0.18),
             CGPoint(x: r.minX + r.width * 0.38, y: r.maxY - r.height * 0.05),
             CGPoint(x: r.minX + r.width * 0.62, y: r.minY + r.height * 0.42),
             CGPoint(x: r.maxX, y: r.minY)], color: color, width: 3.6)
    }

    private static func box(_ r: CGRect, color: UIColor, rough: Bool = false) -> [PKStroke] {
        let o: CGFloat = rough ? 4 : 0
        return [pen([CGPoint(x: r.minX - o, y: r.minY), CGPoint(x: r.maxX + o, y: r.minY + 1),
                     CGPoint(x: r.maxX, y: r.maxY + o), CGPoint(x: r.minX + 1, y: r.maxY),
                     CGPoint(x: r.minX, y: r.minY - o)].enumerated().map { jitter($1, $0) },
                    color: color, width: 2.4)]
    }

    private static func circle(center c: CGPoint, radiusX: CGFloat, radiusY: CGFloat, color: UIColor) -> PKStroke {
        let pts = (0...44).map { i -> CGPoint in
            let t = Double(i) / 40 * 2 * .pi - 0.4   // overshoots like a real hand-drawn loop
            return jitter(CGPoint(x: c.x + CGFloat(cos(t)) * radiusX, y: c.y + CGFloat(sin(t)) * radiusY), i, 0.8)
        }
        return pen(pts, color: color, width: 2.8)
    }

    private static func wavyUnderline(from p: CGPoint, width: CGFloat, color: UIColor) -> PKStroke {
        pen((0...30).map { i in
            let t = CGFloat(i) / 30
            return CGPoint(x: p.x + t * width, y: p.y + sin(t * 9) * 3)
        }, color: color, width: 3)
    }

    private static func arrow(from a: CGPoint, to b: CGPoint, color: UIColor) -> PKStroke {
        let angle = atan2(b.y - a.y, b.x - a.x)
        let head: CGFloat = 16
        let left = CGPoint(x: b.x - head * cos(angle - 0.5), y: b.y - head * sin(angle - 0.5))
        let right = CGPoint(x: b.x - head * cos(angle + 0.5), y: b.y - head * sin(angle + 0.5))
        let mid = CGPoint(x: (a.x + b.x) / 2 + (b.y - a.y) * 0.12, y: (a.y + b.y) / 2 - (b.x - a.x) * 0.12)
        let shaft = (0...16).map { i -> CGPoint in
            let t = CGFloat(i) / 16
            return CGPoint(x: (1 - t) * (1 - t) * a.x + 2 * (1 - t) * t * mid.x + t * t * b.x,
                           y: (1 - t) * (1 - t) * a.y + 2 * (1 - t) * t * mid.y + t * t * b.y)
        }
        return pen(shaft + [left, b, right], color: color, width: 3.2)
    }

    private static func star(center c: CGPoint, radius r: CGFloat, color: UIColor) -> [PKStroke] {
        let pts = (0...5).map { i -> CGPoint in
            let t = Double(i * 2 % 5) / 5 * 2 * .pi - .pi / 2
            return jitter(CGPoint(x: c.x + CGFloat(cos(t)) * r, y: c.y + CGFloat(sin(t)) * r), i)
        }
        return [pen(pts, color: color, width: 3)]
    }

    private static func smile(center c: CGPoint, radius r: CGFloat, color: UIColor) -> [PKStroke] {
        let face = (0...42).map { i -> CGPoint in
            let t = Double(i) / 40 * 2 * .pi
            return jitter(CGPoint(x: c.x + CGFloat(cos(t)) * r, y: c.y + CGFloat(sin(t)) * r), i, 0.6)
        }
        let eyes = [-1, 1].map { side in
            pen([CGPoint(x: c.x + CGFloat(side) * r * 0.36, y: c.y - r * 0.32),
                 CGPoint(x: c.x + CGFloat(side) * r * 0.36, y: c.y - r * 0.12)], color: color, width: 3.2)
        }
        let mouth = (0...16).map { i -> CGPoint in
            let t = Double(i) / 16 * .pi * 0.8 + .pi * 0.1
            return CGPoint(x: c.x + CGFloat(cos(t)) * r * 0.55, y: c.y + r * 0.08 + CGFloat(sin(t)) * r * 0.42)
        }
        return [pen(face, color: color, width: 2.8), pen(mouth, color: color, width: 2.8)] + eyes
    }

    private static func mountains(origin o: CGPoint, width w: CGFloat, height h: CGFloat) -> [PKStroke] {
        let ridge = [CGPoint(x: o.x, y: o.y + h), CGPoint(x: o.x + w * 0.3, y: o.y + h * 0.25),
                     CGPoint(x: o.x + w * 0.45, y: o.y + h * 0.55), CGPoint(x: o.x + w * 0.65, y: o.y + h * 0.05),
                     CGPoint(x: o.x + w, y: o.y + h)]
        let sun = (0...40).map { i -> CGPoint in
            let t = Double(i) / 40 * 2 * .pi
            return CGPoint(x: o.x + w * 0.12 + CGFloat(cos(t)) * 16, y: o.y + h * 0.12 + CGFloat(sin(t)) * 16)
        }
        let waves = (0..<2).map { row in
            pen((0...40).map { i in
                let t = CGFloat(i) / 40
                return CGPoint(x: o.x - 6 + t * (w + 12), y: o.y + h + 14 + CGFloat(row) * 14 + sin(t * 18) * 3)
            }, color: blue, width: 2.6)
        }
        return [pen(ridge.enumerated().map { jitter($1, $0, 1.5) }, color: black, width: 3),
                pen(sun, color: red, width: 2.8)] + waves
    }
}
#endif
